using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
namespace DesktopBox;
internal static class GlassTest {
 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool ShowWindow(IntPtr h,int command);
 internal static void Run(Program app){app.ShutdownMode=ShutdownMode.OnExplicitShutdown;var root=Path.Combine(Path.GetTempPath(),"DesktopBox-GlassTest-"+Guid.NewGuid());Store.PathName=Path.Combine(root,"state.json");var canvas=new Canvas();for(int x=0;x<520;x+=8)canvas.Children.Add(new System.Windows.Shapes.Rectangle{Width=8,Height=400,Fill=x%16==0?Brushes.White:Brushes.RoyalBlue,Margin=new Thickness(x,0,0,0)});var backdrop=new Window{Left=80,Top=80,Width=520,Height=400,WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,Topmost=true,Content=canvas};backdrop.Show();ShowWindow(new System.Windows.Interop.WindowInteropHelper(backdrop).Handle,4);app.Settings.Transparency=95;app.Settings.Frost=1;var config=new BoxConfig{Name="玻璃测试",X=130,Y=130,Width=340,Height=240};app.Settings.Boxes.Add(config);var box=new BoxWindow(app,config){Topmost=true};app.Windows.Add(box);box.Show();ShowWindow(new System.Windows.Interop.WindowInteropHelper(box).Handle,4);var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(800)};int stage=0;double low=0;timer.Tick+=(_,_)=>{try{backdrop.UpdateLayout();var backdropBitmap=new RenderTargetBitmap(520,400,96,96,PixelFormats.Pbgra32);backdropBitmap.Render(backdrop);Save(backdropBitmap,"glass-controlled-pattern.png");box.SampleFrost();box.UpdateLayout();var bitmap=new RenderTargetBitmap((int)box.ActualWidth,(int)box.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(box);var pixels=new byte[(int)box.ActualWidth*(int)box.ActualHeight*4];bitmap.CopyPixels(pixels,(int)box.ActualWidth*4,0);double sum=0,squared=0;int samples=0;for(int x=40;x<300;x++){var index=(120*(int)box.ActualWidth+x)*4;double red=pixels[index+2];sum+=red;squared+=red*red;samples++;}var variance=squared/samples-Math.Pow(sum/samples,2);Save(bitmap,stage==0?"glass-low-frost.png":"glass-high-frost.png");if(stage++==0){low=variance;if(low<100)throw new Exception("Background pattern was not captured; box="+BackgroundSampler.Info(box)+" backdrop="+BackgroundSampler.Info(backdrop)+" variance="+low);app.SetFrost(100);}else{if(variance>=low*0.25)throw new Exception("Frost did not blur backdrop");var center=(120*(int)box.ActualWidth+160)*4;if(pixels[center+3]>=255||pixels[3]!=0)throw new Exception("Glass transparency or corners invalid");if(box.TintAlpha!=13||box.FrostRadius!=30)throw new Exception("Frost changed tint instead of blur radius");var reloaded=Store.Load();if(reloaded.Transparency!=95||reloaded.Frost!=100)throw new Exception("Global material settings not persisted");File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"glass-test.txt"),$"PASS: controlled background sampled only in memory; blur variance {low:F2} -> {variance:F2}; independent blur radius and tint; alpha and rounded corner; global material persistence. Screenshots use only test-owned stripes.");Cleanup();app.Shutdown();}}catch(Exception ex){File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"glass-test.txt"),ex.ToString());Cleanup();app.Shutdown(1);}};timer.Start();void Cleanup(){timer.Stop();box.DisposeAndClose();app.Windows.Clear();backdrop.Close();if(Directory.Exists(root))Directory.Delete(root,true);}}
 static void Save(BitmapSource bitmap,string file){var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var stream=File.Create(Path.Combine(AppContext.BaseDirectory,file));encoder.Save(stream);}
}



